var NAMED = {black:[0,0,0], white:[255,255,255], red:[255,0,0], gray:[128,128,128], grey:[128,128,128]};

function round2(v){ return Math.round(v*100)/100; }
function round3(v){ return Math.round(v*1000)/1000; }
function clamp(v,a,b){ return v<a?a:(v>b?b:v); }
function fmt(v){
  var n=round2(Number(v)||0);
  return (n===Math.floor(n)) ? String(Math.floor(n)) : String(n);
}

function hexToRgb(hex){
  if(hex==null) return {r:0,g:0,b:0,a:1};
  var s=String(hex).trim().toLowerCase();
  if(NAMED[s]) return {r:NAMED[s][0], g:NAMED[s][1], b:NAMED[s][2], a:1};
  if(s === 'transparent') return {r:0,g:0,b:0,a:0};
  s=s.replace(/^#/,'');
  if(s.length===3||s.length===4){
    var p=s.split('');
    var o={r:parseInt(p[0]+p[0],16), g:parseInt(p[1]+p[1],16), b:parseInt(p[2]+p[2],16), a:1};
    if(s.length===4) o.a=round3(parseInt(p[3]+p[3],16)/255);
    return o;
  }
  if(s.length===6||s.length===8){
    var o2={r:parseInt(s.slice(0,2),16), g:parseInt(s.slice(2,4),16), b:parseInt(s.slice(4,6),16), a:1};
    if(s.length===8) o2.a=round3(parseInt(s.slice(6,8),16)/255);
    return o2;
  }
  return {r:0,g:0,b:0,a:1};
}

function rgbToHex(c){
  function h(v){ var s=clamp(Math.round(v),0,255).toString(16); return s.length<2?'0'+s:s; }
  return '#'+h(c.r)+h(c.g)+h(c.b);
}

function rgbaStr(color, alpha){
  var c=hexToRgb(color);
  var a=alpha==null?c.a:alpha;
  return 'rgba('+Math.round(c.r)+', '+Math.round(c.g)+', '+Math.round(c.b)+', '+round3(clamp(a,0,1))+')';
}

function normLayer(l){
  l=l||{};
  return {x:Number(l.x)||0, y:Number(l.y)||0, blur:Number(l.blur)||0, spread:Number(l.spread)||0,
          color:l.color||'#000000', alpha:l.alpha==null?0.15:clamp(Number(l.alpha),0,1),
          inset:!!l.inset};
}

function layerCss(l, type){
  var n=normLayer(l);
  var col=rgbaStr(n.color, n.alpha);
  if(type==='text') return fmt(n.x)+'px '+fmt(n.y)+'px '+fmt(n.blur)+'px '+col;
  if(type==='drop') return 'drop-shadow('+fmt(n.x)+'px '+fmt(n.y)+'px '+fmt(n.blur)+'px '+col+')';
  return (n.inset?'inset ':'')+fmt(n.x)+'px '+fmt(n.y)+'px '+fmt(n.blur)+'px '+fmt(n.spread)+'px '+col;
}

function shadowCss(layers, type, multiline){
  layers=layers||[];
  if(!layers.length) return 'none';
  var t=type||'box';
  var parts=layers.map(function(l){ return layerCss(l,t); });
  if(t==='drop') return parts.join(' ');
  return parts.join(multiline ? ',\n    ' : ', ');
}

function propertyName(type){
  if(type==='text') return 'text-shadow';
  if(type==='drop') return 'filter';
  return 'box-shadow';
}

function cssRule(sel, layers, type, multiline){
  return (sel||'.card')+' {\n  '+propertyName(type)+': '+shadowCss(layers,type,multiline)+';\n}';
}

function splitTop(s){
  var out=[], depth=0, cur='';
  for(var i=0;i<s.length;i++){
    var c=s[i];
    if(c==='(') depth++;
    if(c===')') depth--;
    if(c===',' && depth===0){ out.push(cur); cur=''; continue; }
    cur+=c;
  }
  if(cur.trim()) out.push(cur);
  return out.map(function(x){ return x.trim(); }).filter(function(x){ return x.length; });
}

function parseColorToken(part){
  var m=/rgba?\(([^)]*)\)/i.exec(part);
  if(m){
    var n=m[1].split(',').map(function(x){ return parseFloat(x.trim()); });
    return {color:rgbToHex({r:n[0]||0,g:n[1]||0,b:n[2]||0}), alpha: n.length>3 ? round3(n[3]) : 1,
            raw:m[0]};
  }
  var h=/#[0-9a-fA-F]{3,8}\b/.exec(part);
  if(h){ var c=hexToRgb(h[0]); return {color:rgbToHex(c), alpha:c.a, raw:h[0]}; }
  var keys=Object.keys(NAMED);
  for(var i=0;i<keys.length;i++){
    var re=new RegExp('\\b'+keys[i]+'\\b','i');
    if(re.test(part)){ var k=NAMED[keys[i]]; return {color:rgbToHex({r:k[0],g:k[1],b:k[2]}), alpha:1, raw:keys[i]}; }
  }
  return {color:'#000000', alpha:1, raw:null};
}

function parseShadow(str){
  if(str==null) return [];
  var s=String(str).replace(/^\s*(box-shadow|text-shadow|filter)\s*:\s*/i,'').replace(/;\s*$/,'').trim();
  if(!s || s==='none') return [];
  if(/drop-shadow\s*\(/i.test(s)){
    var res=[], re=/drop-shadow\s*\(([^()]*(?:\([^()]*\)[^()]*)*)\)/gi, mm;
    while((mm=re.exec(s))!==null){ res.push(parseOne(mm[1], false)); }
    return res;
  }
  return splitTop(s).map(function(p){
    var inset=/\binset\b/i.test(p);
    return parseOne(p.replace(/\binset\b/ig,''), inset);
  });
}

function parseOne(part, inset){
  var col=parseColorToken(part);
  var rest = col.raw ? part.replace(col.raw,' ') : part;
  var nums=(rest.match(/-?\d*\.?\d+/g)||[]).map(parseFloat);
  return {x:nums[0]||0, y:nums[1]||0, blur:nums[2]||0, spread:nums[3]||0,
          color:col.color, alpha:col.alpha, inset:!!inset};
}

function smoothRamp(o){
  o=o||{};
  var n=Math.max(1, Math.round(o.layers==null?5:o.layers));
  var Y=o.y==null?24:o.y, B=o.blur==null?48:o.blur, S=o.spread==null?0:o.spread;
  var A=o.alpha==null?0.16:o.alpha, color=o.color||'#000000';
  var exp=o.curve==null?2:o.curve, X=o.x==null?0:o.x;
  var out=[];
  for(var i=1;i<=n;i++){
    var f=Math.pow(i/n, exp);
    out.push({x:round2(X*f), y:round2(Y*f), blur:round2(B*f), spread:round2(S*f),
              color:color, alpha:round3(A/n), inset:false});
  }
  return out;
}

var ELEVATIONS = {
  0: [],
  1: [{x:0,y:1,blur:2,spread:0,alpha:0.08},{x:0,y:1,blur:3,spread:0,alpha:0.06}],
  2: [{x:0,y:2,blur:4,spread:-1,alpha:0.10},{x:0,y:4,blur:6,spread:-1,alpha:0.07}],
  3: [{x:0,y:4,blur:8,spread:-2,alpha:0.12},{x:0,y:8,blur:16,spread:-4,alpha:0.08}],
  4: [{x:0,y:8,blur:16,spread:-4,alpha:0.14},{x:0,y:16,blur:32,spread:-8,alpha:0.10}],
  5: [{x:0,y:16,blur:32,spread:-8,alpha:0.16},{x:0,y:32,blur:64,spread:-16,alpha:0.12}]
};

function elevation(level, color){
  var lv=clamp(Math.round(Number(level)||0),0,5);
  return (ELEVATIONS[lv]||[]).map(function(l){
    return {x:l.x,y:l.y,blur:l.blur,spread:l.spread,color:color||'#000000',alpha:l.alpha,inset:false};
  });
}

function totalAlpha(layers){
  var t=0;
  (layers||[]).forEach(function(l){ t += normLayer(l).alpha; });
  return round3(t);
}

function invert(layers){
  return (layers||[]).map(function(l){
    var n=normLayer(l); n.y=-n.y; n.x=-n.x; return n;
  });
}

function toCssVar(name, layers, type){
  return '--'+(name||'shadow')+': '+shadowCss(layers,type)+';';
}

function toTailwind(layers, type){
  var s=shadowCss(layers,type).replace(/,\s+/g,',').replace(/\s+/g,'_');
  return (type==='text'?'[text-shadow:':'shadow-[')+s+']';
}

function lint(layers, type){
  layers=layers||[];
  var w=[];
  if(!layers.length){ return [{level:'info', msg:'当前没有任何阴影层，输出为 none'}]; }
  var ta=totalAlpha(layers);
  if(ta>0.6) w.push({level:'warn', msg:'累计不透明度 '+ta+' 偏高，暗色界面上容易糊成一团，建议 ≤ 0.4'});
  if(layers.length>8) w.push({level:'warn', msg:layers.length+' 层阴影会显著增加合成绘制成本，移动端建议 ≤ 6 层'});
  layers.forEach(function(l,i){
    var n=normLayer(l);
    if(n.blur===0 && n.spread===0 && (n.x!==0||n.y!==0))
      w.push({level:'info', msg:'第 '+(i+1)+' 层 blur 与 spread 均为 0，会是硬边偏移（Neo-brutalism 常用，若想要柔和请加 blur）'});
    if(n.blur>0 && n.blur < Math.abs(n.y))
      w.push({level:'info', msg:'第 '+(i+1)+' 层 blur('+n.blur+') 远小于 y 偏移('+n.y+')，投影会显得生硬'});
    if(n.y<0 && n.blur>16)
      w.push({level:'info', msg:'第 '+(i+1)+' 层 y 为负且模糊很大，等于光源来自下方，与常见自上而下光照不符'});
    if(n.alpha>=0.5)
      w.push({level:'warn', msg:'第 '+(i+1)+' 层 alpha='+n.alpha+' 过重，单层建议 ≤ 0.25 并用多层叠加'});
    if(type==='text' && (n.spread!==0))
      w.push({level:'error', msg:'第 '+(i+1)+' 层设置了 spread，但 text-shadow 不支持 spread，导出时会被丢弃'});
    if(type==='text' && n.inset)
      w.push({level:'error', msg:'第 '+(i+1)+' 层是 inset，但 text-shadow 不支持 inset'});
    if(type==='drop' && n.inset)
      w.push({level:'error', msg:'第 '+(i+1)+' 层是 inset，但 filter: drop-shadow() 不支持 inset'});
    if(type==='drop' && n.spread!==0)
      w.push({level:'warn', msg:'第 '+(i+1)+' 层的 spread 在 drop-shadow() 中无效，将被忽略'});
  });
  var insets=layers.filter(function(l){ return normLayer(l).inset; }).length;
  if(insets && insets<layers.length && type!=='text' && type!=='drop')
    w.push({level:'info', msg:'同时存在 inset 与外阴影 '+insets+'/'+layers.length+'，注意 inset 会绘制在内容之下'});
  return w;
}

var ShadowForgePure = {
  hexToRgb:hexToRgb, rgbToHex:rgbToHex, rgbaStr:rgbaStr, normLayer:normLayer,
  layerCss:layerCss, shadowCss:shadowCss, propertyName:propertyName, cssRule:cssRule,
  splitTop:splitTop, parseShadow:parseShadow, smoothRamp:smoothRamp, elevation:elevation,
  totalAlpha:totalAlpha, invert:invert, toCssVar:toCssVar, toTailwind:toTailwind, lint:lint, fmt:fmt
};
if (typeof module !== 'undefined' && module.exports) module.exports = ShadowForgePure;
if (typeof window !== 'undefined') window.ShadowForgePure = ShadowForgePure;
